widget.solution:
def is_hom(f, n, m):
    """f[x] is the image of x; f maps Z_n to Z_m."""
    return all(f[(a + b) % n] == (f[a] + f[b]) % m
               for a in range(n) for b in range(n))


def kernel(f):
    """Sorted list of the x with f[x] == 0."""
    return [x for x, y in enumerate(f) if y == 0]
